-- Seed data for BetterX (MySQL-compatible)
-- Run after `sequelize.sync()` has created the tables.
-- All passwords hash to the same value (shared dev password).

SET NAMES utf8mb4;

CREATE DATABASE IF NOT EXISTS betterx CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE betterx;

CREATE TABLE IF NOT EXISTS `users` (
  `id`         CHAR(36)     NOT NULL,
  `name`       VARCHAR(255) NOT NULL,
  `username`   VARCHAR(255) NOT NULL,
  `password`   VARCHAR(255) NOT NULL,
  `avatar_url` TEXT         NULL,
  `created_at` DATETIME     NOT NULL,
  `updated_at` DATETIME     NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `posts` (
  `id`         CHAR(36)     NOT NULL,
  `user_id`    CHAR(36)     NOT NULL,
  `title`      VARCHAR(255) NOT NULL,
  `body`       TEXT         NOT NULL,
  `image_url`  VARCHAR(255) NULL,
  `created_at` DATETIME     NOT NULL,
  `updated_at` DATETIME     NOT NULL,
  PRIMARY KEY (`id`),
  CONSTRAINT `posts_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `comments` (
  `id`         CHAR(36) NOT NULL,
  `post_id`    CHAR(36) NOT NULL,
  `user_id`    CHAR(36) NULL,
  `parent_id`  CHAR(36) NULL,
  `body`       TEXT     NOT NULL,
  `created_at` DATETIME NOT NULL,
  `updated_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`),
  CONSTRAINT `comments_post_id` FOREIGN KEY (`post_id`)   REFERENCES `posts`    (`id`) ON DELETE CASCADE  ON UPDATE CASCADE,
  CONSTRAINT `comments_user_id` FOREIGN KEY (`user_id`)   REFERENCES `users`    (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `comments_parent_id` FOREIGN KEY (`parent_id`) REFERENCES `comments` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `follows` (
  `follower_id` CHAR(36) NOT NULL,
  `followee_id` CHAR(36) NOT NULL,
  `created_at`  DATETIME NOT NULL,
  `updated_at`  DATETIME NOT NULL,
  PRIMARY KEY (`follower_id`, `followee_id`),
  CONSTRAINT `follows_follower_id` FOREIGN KEY (`follower_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `follows_followee_id` FOREIGN KEY (`followee_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `likes` (
  `id`         CHAR(36)    NOT NULL,
  `user_id`    CHAR(36)    NOT NULL,
  `post_id`    CHAR(36)    NULL,
  `comment_id` CHAR(36)    NULL,
  `emoji`      VARCHAR(10) NOT NULL,
  `created_at` DATETIME    NOT NULL,
  `updated_at` DATETIME    NOT NULL,
  PRIMARY KEY (`id`),
  CONSTRAINT `likes_user_id`    FOREIGN KEY (`user_id`)    REFERENCES `users`    (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `likes_post_id`    FOREIGN KEY (`post_id`)    REFERENCES `posts`    (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `likes_comment_id` FOREIGN KEY (`comment_id`) REFERENCES `comments` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `notifications` (
  `id`           CHAR(36)                        NOT NULL,
  `recipient_id` CHAR(36)                        NOT NULL,
  `actor_id`     CHAR(36)                        NULL,
  `type`         ENUM('comment','follow','post')  NOT NULL,
  `post_id`      CHAR(36)                        NULL,
  `comment_id`   CHAR(36)                        NULL,
  `read`         TINYINT(1)                      NOT NULL DEFAULT 0,
  `created_at`   DATETIME                        NOT NULL,
  `updated_at`   DATETIME                        NOT NULL,
  PRIMARY KEY (`id`),
  CONSTRAINT `notif_recipient_id` FOREIGN KEY (`recipient_id`) REFERENCES `users`    (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `notif_actor_id`     FOREIGN KEY (`actor_id`)     REFERENCES `users`    (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `notif_post_id`      FOREIGN KEY (`post_id`)      REFERENCES `posts`    (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `notif_comment_id`   FOREIGN KEY (`comment_id`)   REFERENCES `comments` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

SET FOREIGN_KEY_CHECKS=0;

