INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('c1000001-0000-4000-8000-000000000001', 'a1b2c3d4-0001-4000-8000-000000000001', '4b1193cc-7ba1-462c-99c5-2e3ea4ab6d14', 'Fully agree! Migrating our codebase to TypeScript cut our runtime bugs by half. The initial setup is a bit annoying but totally worth it.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('c1000001-0000-4000-8000-000000000002', 'a1b2c3d4-0001-4000-8000-000000000001', 'bff2018c-b130-4de4-b645-3246b6e4dbb6', 'I resisted TS for a long time but now I cannot imagine going back. The type inference in modern versions is incredible.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('c1000001-0000-4000-8000-000000000003', 'a1b2c3d4-0001-4000-8000-000000000001', '00ddb751-ad1b-437c-b7d3-44b42f0e13f7', 'Thanks for the feedback! TypeScript strict mode is a game-changer ÔÇö highly recommend enabling it from day one.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('c1000002-0000-4000-8000-000000000001', 'a1b2c3d4-0002-4000-8000-000000000002', '034485be-cfd2-48a7-b80d-f54773eab18c', 'Docker compose is what really sold me. Spinning up a full local stack with one command is pure magic for development.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('c1000002-0000-4000-8000-000000000002', 'a1b2c3d4-0002-4000-8000-000000000002', '57ca1e6a-fc89-4d28-ad45-a1f351862cfc', 'Containers are great but the learning curve on networks and volumes trips up everyone at first. Good write-up!', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('c1000002-0000-4000-8000-000000000003', 'a1b2c3d4-0002-4000-8000-000000000002', '071152a6-6c92-4e73-b5d2-2797d9a0a748', 'Podman is also worth looking into as a rootless Docker alternative. Same CLI, better security story.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('c1000002-0000-4000-8000-000000000004', 'a1b2c3d4-0002-4000-8000-000000000002', '00ddb751-ad1b-437c-b7d3-44b42f0e13f7', 'Good point Vladimir! I have been meaning to try Podman, especially on Linux where it shines.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('c1000003-0000-4000-8000-000000000001', 'a1b2c3d4-0003-4000-8000-000000000003', '1230ae30-dc4f-4752-bd84-092956f5c633', 'AI tools are impressive but I worry about junior devs not learning fundamentals if they rely on copilot from day one.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('c1000003-0000-4000-8000-000000000002', 'a1b2c3d4-0003-4000-8000-000000000003', '4b1193cc-7ba1-462c-99c5-2e3ea4ab6d14', 'Productivity boost is real. I was skeptical too but now I use it daily for tests and boilerplate ÔÇö saves hours.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('c1000003-0000-4000-8000-000000000003', 'a1b2c3d4-0003-4000-8000-000000000003', '00ddb751-ad1b-437c-b7d3-44b42f0e13f7', 'Fair concern Bob! I think the key is to always review what the AI generates instead of accepting blindly.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('c2000001-0000-4000-8000-000000000001', 'b9c8d7e6-0001-4000-8000-000000000004', '00ddb751-ad1b-437c-b7d3-44b42f0e13f7', 'We switched to tRPC which gives type-safe APIs without the full GraphQL complexity. Best of both worlds!', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('c2000001-0000-4000-8000-000000000002', 'b9c8d7e6-0001-4000-8000-000000000004', '4b1193cc-7ba1-462c-99c5-2e3ea4ab6d14', 'GraphQL resolves the n+1 problem nicely with DataLoader. The tooling has matured a lot recently.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('c2000001-0000-4000-8000-000000000003', 'b9c8d7e6-0001-4000-8000-000000000004', 'bff2018c-b130-4de4-b645-3246b6e4dbb6', 'REST with OpenAPI specs is still my go-to for public APIs. GraphQL is ideal for internal BFF layers though.', NOW(), NOW());
