INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('c2000002-0000-4000-8000-000000000001', 'b9c8d7e6-0002-4000-8000-000000000005', '57ca1e6a-fc89-4d28-ad45-a1f351862cfc', 'Socket.io made WebSockets approachable back in the day. Now the native API is good enough for most use cases.', NOW(), NOW());
