INSERT INTO follows (follower_id, followee_id, created_at, updated_at) VALUES ('1230ae30-dc4f-4752-bd84-092956f5c633', '034485be-cfd2-48a7-b80d-f54773eab18c', NOW(), NOW());
INSERT INTO posts (id, user_id, title, body, image_url, created_at, updated_at) VALUES ('ux000001-0000-4000-8000-000000000001', '2f51d803-34cf-48b8-b454-bd017f006831', 'The Psychology of Color in UI Design', 'Color drives 85% of purchase decisions before users read a single word. The right palette creates emotion, guides attention, and builds brand trust instantly. In UI design every shade is a silent conversation with your user — and most designers are not listening closely enough.', 'https://picsum.photos/seed/colorux/600/400', NOW(), NOW());
INSERT INTO posts (id, user_id, title, body, image_url, created_at, updated_at) VALUES ('ux000002-0000-4000-8000-000000000002', '2f51d803-34cf-48b8-b454-bd017f006831', 'Why Whitespace Is Your Best Design Tool', 'Negative space is not emptiness — it is breathing room. When elements have space to exist, users can focus, comprehend, and interact without cognitive overload. The best UIs use whitespace as deliberately as any visible element. Stop filling every pixel and start letting your design breathe.', 'https://picsum.photos/seed/whitespaceui/600/400', NOW(), NOW());
INSERT INTO posts (id, user_id, title, body, image_url, created_at, updated_at) VALUES ('ux000003-0000-4000-8000-000000000003', '2f51d803-34cf-48b8-b454-bd017f006831', 'Microinteractions That Delight Users', 'A button that bounces on tap, a checkbox that transforms with a satisfying click, a skeleton screen instead of a spinner — these are microinteractions. They cost milliseconds of attention but earn minutes of trust. The difference between a product users tolerate and one they love is almost always the details.', 'https://picsum.photos/seed/microux/600/400', NOW(), NOW());
INSERT INTO posts (id, user_id, title, body, image_url, created_at, updated_at) VALUES ('ux000004-0000-4000-8000-000000000004', '2f51d803-34cf-48b8-b454-bd017f006831', 'Mobile-First Design Is Non-Negotiable', 'Over 60% of global web traffic is mobile. Designing for the small screen first is not a constraint — it is good strategy. Mobile-first forces you to prioritize ruthlessly, which almost always produces a cleaner desktop experience too. Building desktop-first in 2026 means ignoring the majority of your users.', 'https://picsum.photos/seed/mobilefirstux/600/400', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('cux10001-0000-4000-8000-000000000001', 'ux000001-0000-4000-8000-000000000001', '4b1193cc-7ba1-462c-99c5-2e3ea4ab6d14', 'We A/B tested our CTA button — switching from grey to orange increased conversions by 27%. Color really is everything.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('cux10001-0000-4000-8000-000000000002', 'ux000001-0000-4000-8000-000000000001', '00ddb751-ad1b-437c-b7d3-44b42f0e13f7', 'The cultural context of color is so often overlooked. Red signals danger in the West but luck and prosperity in China.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('cux10001-0000-4000-8000-000000000003', 'ux000001-0000-4000-8000-000000000001', 'bff2018c-b130-4de4-b645-3246b6e4dbb6', 'Accessibility matters here too — 8% of men are color-blind. A good UI never relies on color alone to convey meaning.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('cux10002-0000-4000-8000-000000000001', 'ux000002-0000-4000-8000-000000000002', '1230ae30-dc4f-4752-bd84-092956f5c633', 'Every junior designer I mentor tries to fill every pixel. Teaching them to embrace emptiness is the hardest lesson.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('cux10002-0000-4000-8000-000000000002', 'ux000002-0000-4000-8000-000000000002', '57ca1e6a-fc89-4d28-ad45-a1f351862cfc', 'Apple built their entire brand identity around whitespace. It signals quality and confidence before you read a word.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('cux10002-0000-4000-8000-000000000003', 'ux000002-0000-4000-8000-000000000002', '034485be-cfd2-48a7-b80d-f54773eab18c', 'Cluttered dashboards that try to surface every metric at once are a UX crime. Less is almost always more.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('cux10003-0000-4000-8000-000000000001', 'ux000003-0000-4000-8000-000000000003', '071152a6-6c92-4e73-b5d2-2797d9a0a748', 'We replaced our loading spinner with a skeleton screen and complaints about slow load times dropped by more than half.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('cux10003-0000-4000-8000-000000000002', 'ux000003-0000-4000-8000-000000000003', '4b1193cc-7ba1-462c-99c5-2e3ea4ab6d14', 'The satisfaction of a well-crafted checkbox animation is genuinely hard to explain until you feel it yourself.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('cux10003-0000-4000-8000-000000000003', 'ux000003-0000-4000-8000-000000000003', '57ca1e6a-fc89-4d28-ad45-a1f351862cfc', 'Microinteractions build trust. When an action feels responsive, users feel in control of the interface.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('cux10004-0000-4000-8000-000000000001', 'ux000004-0000-4000-8000-000000000004', '00ddb751-ad1b-437c-b7d3-44b42f0e13f7', 'Tried retrofitting mobile onto a desktop-first app once. The rework cost three times the original build estimate.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('cux10004-0000-4000-8000-000000000002', 'ux000004-0000-4000-8000-000000000004', '1230ae30-dc4f-4752-bd84-092956f5c633', '44x44px minimum touch targets saved our support team from hundreds of ''the button is too small'' tickets per week.', NOW(), NOW());
INSERT INTO comments (id, post_id, user_id, body, created_at, updated_at) VALUES ('cux10004-0000-4000-8000-000000000003', 'ux000004-0000-4000-8000-000000000004', 'bff2018c-b130-4de4-b645-3246b6e4dbb6', 'Mobile-first also forces you to kill every non-essential feature. Constraints are a design tool in disguise.', NOW(), NOW());
